from pathlib import Path
import subprocess
root=Path(__file__).resolve().parents[1]
source=(root/'overlay/src/modules/optional/SentinelPresence/SentinelPresence.cpp').read_text()
methods=source[source.index('    bool localObservation'):source.index('  protected:')]+source[source.index('    sentinelObservation::Queue observations;'):source.index('    void initialize()')]
prefix='#include <cassert>\n#include <vector>\n#include <cstdio>\n#include "../overlay/src/modules/optional/SentinelPresence/SentinelCore.h"\n#include "../overlay/src/modules/optional/SentinelPresence/SentinelObservation.h"\nbool observationEnabled=false;uint16_t observationInterval=15;\n#include <deque>\n#include <algorithm>\nuint32_t clockMs=0;\nuint32_t millis(){return clockMs;}\nconstexpr int meshtastic_PortNum_PRIVATE_APP=256,meshtastic_PortNum_TEXT_MESSAGE_APP=1,RTCQualityDevice=1;\nuint32_t getValidTime(int){return 1791972000;}\nconstexpr int meshtastic_Channel_Role_DISABLED=0,meshtastic_Channel_Role_SECONDARY=2;\nconstexpr int meshtastic_Config_LoRaConfig_RegionCode_UNSET=0,RX_SRC_LOCAL=0;\nstruct Log {template<class... A> void printf(const char*,A...) {}} Serial;\nstruct meshtastic_MeshPacket {\n uint32_t id=12345678,from=42,to=99;unsigned channel=0,hop_limit=0;bool want_ack=false,via_mqtt=false;\n struct {int portnum=256;struct {uint8_t bytes[237]={};size_t size=0;}payload;}decoded;\n};\nstruct Key {unsigned size=32;uint8_t bytes[32]={7};};\nstruct Channel {int role=1;bool has_settings=true;struct {Key psk;}settings;};\nstruct Channels {Channel ch;unsigned getNumChannels(){return 1;}unsigned getPrimaryIndex(){return 0;}Channel&getByIndex(unsigned){return ch;}}channels;\nstruct {struct {int region=1;bool tx_enabled=true;}lora;}config;\nstruct Node {unsigned getNodeNum(){return 99;}}node;Node*nodeDB=&node;\nstruct Service {std::vector<meshtastic_MeshPacket> sent;void sendToMesh(meshtastic_MeshPacket*p,int,bool){sent.push_back(*p);delete p;}}mesh;Service*service=&mesh;\nenum class ProcessMessage {CONTINUE};\nstruct Base {meshtastic_MeshPacket*allocDataPacket(){return new meshtastic_MeshPacket;}};\nSentinelSettings settings{};\nclass Bridge:public Base {public: bool initialized=true,portalActive=false;\n'
tests='\n};\nint main(){\n Bridge node;uint8_t input[]={\'S\',\'O\',\'I\',\'1\',1,0,0,0,0xf0,0x23,1,0,0,0,4,\'F\',\'I\',\'R\',\'E\'};\n assert(node.localObservation(99,256,input,sizeof(input)));assert(!node.observations.size);\n observationEnabled=true;settings.meshOutput=true;\n node.portalActive=true;node.localObservation(99,256,input,sizeof(input));assert(!node.observations.size);\n node.portalActive=false;\n node.localObservation(100,256,input,sizeof(input));assert(!node.observations.size);\n assert(!node.localObservation(99,1,input,sizeof(input)));\n input[3]=\'2\';node.localObservation(99,256,input,sizeof(input));assert(!node.observations.size);input[3]=\'1\';\n clockMs=10000;node.localObservation(99,256,input,sizeof(input));assert(node.observations.size==1);\n node.localObservation(99,256,input,sizeof(input));assert(node.observations.size==1);\n channels.ch.settings.psk.size=1;node.pollObservations(clockMs);assert(mesh.sent.empty());\n channels.ch.settings.psk.size=32;config.lora.tx_enabled=false;node.pollObservations(clockMs);assert(mesh.sent.empty());\n config.lora.tx_enabled=true;node.pollObservations(clockMs);assert(mesh.sent.size()==1 && !node.observations.size);\n auto &p=mesh.sent[0];assert(p.decoded.portnum==1);assert(!memcmp(p.decoded.payload.bytes,"X1.11.C.",8));\n clockMs+=15000;input[4]=2;node.localObservation(99,256,input,sizeof(input));assert(node.observations.size==1);\n node.pollObservations(clockMs);assert(mesh.sent.size()==2);\n clockMs+=15000;input[4]=3;node.localObservation(99,256,input,sizeof(input));\n node.pollObservations(clockMs+30000);assert(!node.observations.size && mesh.sent.size()==2);\n puts("PASS actual local ingress, disabled/portal/destination/version gates, duplicates, private TX, rate and expiry");\n}\n'
out=root/'.build/ground-integration';out.mkdir(parents=True,exist_ok=True)
cpp=out/'ground.cpp';cpp.write_text(prefix+methods+tests)
exe=out/'ground.exe'
subprocess.run(['g++','-std=c++17','-Wall','-Wextra','-Werror','-I'+str(root/'tests'),str(cpp),'-o',str(exe)],check=True)
subprocess.run([str(exe)],check=True)
